const input = $input.first().json;
const rawQuery = input.keyword || input.query || input.input || 'statistik';

// Stopwords yang lebih lengkap - termasuk kata umum yang tidak bermakna
const stopwords = [
  'kota','pekanbaru','tahun','berapa','apa','data','statistik',
  'yang','untuk','pada','bulan','adalah','jumlah','total',
  'kecamatan','kelurahan','terbaru','terkini','berikan','tolong',
  'bisa','mohon','info','informasi','tentang','mengenai','dari',
  'di','dan','atau','dengan','dalam','ada'
];

const words = String(rawQuery).toLowerCase()
  .replace(/[^a-z0-9\s]/g, ' ')
  .split(/\s+/)
  .filter(w => w.length > 3 && !stopwords.includes(w));

// Ambil 2 kata paling relevan (bukan hanya 1)
const keyword = words.slice(0, 2).join(' ') || rawQuery || 'statistik';

return [{ json: { keyword } }];

const pressData = $('BPS Pressrelease').first().json;
const statData = $('BPS Statictable').first().json;
const keyword = $('Extract Keyword').first().json.keyword;
const stripHtml = (s) => String(s || '').replace(/&lt;[^&]*?&gt;/g, ' ').replace(/&nbsp;/g, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
let press = [];
if (pressData && pressData.data && Array.isArray(pressData.data) && pressData.data.length > 1) {
  press = pressData.data[1] || [];
}
let stat = [];
if (statData && statData.data && Array.isArray(statData.data) && statData.data.length > 1) {
  stat = statData.data[1] || [];
}
let out;
if (press.length === 0 && stat.length === 0) {
  out = 'Tidak ada hasil di API BPS Pekanbaru untuk keyword "' + keyword + '".';
} else {
  out = 'Data BPS Kota Pekanbaru (keyword: "' + keyword + '"):\n\n';
  if (press.length > 0) {
    out += 'Siaran Pers:\n';
    press.forEach((p, i) => {
      out += '[' + (i+1) + '] ' + p.title + ' (' + p.rl_date + ')\n';
      out += stripHtml(p.abstract).slice(0, 300) + '\n\n';
    });
  }
  if (stat.length > 0) {
    out += 'Tabel Statistik:\n';
    stat.forEach((t, i) => { out += '[' + (i+1) + '] ' + t.title + ' (' + t.updt_date + ')\n'; });
  }
}
return [{ json: { response: out } }];
